# Break My Fix finding 4, generated by Tracefix: Env.db_url_config returns a wrong value.
# Property (docstring): Every key/value of a non-empty extra_options dict appears in result['OPTIONS'] for any URL with a known scheme, including the special sqlite in-memory URL
# Quote: Optional dictionary merged into ``OPTIONS`` after URL parsing.
# Run it with pytest: it fails for as long as the code breaks this property.

from environ.environ import Env


def test_break_my_fix_4() -> None:
    url = 'sqlite://:memory:'
    engine = None
    options_cast = None
    extra_options = {'timeout': 20}
    # The property applies to this input: isinstance(url, str) and isinstance(extra_options, dict) and len(extra_options) > 0 and url.split('://')[0] in Env.DB_SCHEMES and engine is None and options_cast is None
    result = Env.db_url_config(url=url, engine=engine, options_cast=options_cast, extra_options={'timeout': 20})
    assert (isinstance(result.get('OPTIONS'), dict) and all(k in result['OPTIONS'] and result['OPTIONS'][k] == v for k, v in extra_options.items()))
